32: # chat persistence helpers ----------------------------------------------------
33: 
34: should_persist <- function() {
35:   interactive() || identical(Sys.getenv("NOT_CRAN"), "true")
36: }
37: 
38: get_chat_dir <- function(path = getwd(), persist = NULL) {
39:   if (is.null(persist)) {
40:     persist <- should_persist()
41:   }
42: 
43:   if (!persist) {
44:     return(file.path(tempdir(), "side_chats"))
45:   }
46: 
47:   dir_basename <- basename(normalizePath(path, mustWork = FALSE))
48: 
49:   if (.Platform$OS.type == "windows") {
50:     base_dir <- file.path(Sys.getenv("APPDATA"), "side", "chats")
51:   } else {
52:     base_dir <- file.path(Sys.getenv("HOME"), ".config", "side", "chats")
53:   }
54: 
55:   file.path(base_dir, dir_basename)
56: }
57: 
58: get_chat_files <- function(path = getwd(), persist = NULL) {
59:   chat_dir <- get_chat_dir(path, persist = persist)
60: 
61:   if (!dir.exists(chat_dir)) {
62:     return(character(0))
63:   }
64: 
65:   files <- list.files(chat_dir, pattern = "\\.rds$", full.names = TRUE)
66: 
67:   if (length(files) == 0) {
68:     return(character(0))
69:   }
70: 
71:   info <- file.info(files)
72:   files[order(info$mtime, decreasing = TRUE)]
73: }
74: 
75: get_chat_label <- function(chat_file) {
76:   if (!file.exists(chat_file)) {
77:     return("Unknown chat")
78:   }
79: 
80:   tryCatch(
81:     {
82:       client <- readRDS(chat_file)
83:       turns <- client$get_turns()
84:       user_turns <- Filter(function(turn) turn@role == "user", turns)
85: 
86:       first_words <- if (length(user_turns) == 0) {
87:         "New conversation"
88:       } else {
89:         text <- extract_first_text(user_turns[[1]])
90:         if (is.null(text) || nchar(trimws(text)) == 0) {
91:           "New conversation"
92:         } else {
93:           truncate_text(text)
94:         }
95:       }
96: 
97:       mtime <- file.info(chat_file)$mtime
98:       paste0(first_words, " (", format(mtime, "%d-%m-%Y %H:%M"), ")")
99:     },
100:     error = function(e) {
101:       "Invalid chat file"
102:     }
103:   )
104: }
105: 
106: extract_first_text <- function(turn) {
107:   text_contents <- Filter(
108:     function(c) {
109:       inherits(c, "ContentText") || inherits(c, "ellmer::ContentText")
110:     },
111:     turn@contents
112:   )
113:   if (length(text_contents) > 0 && !is.null(text_contents[[1]]@text)) {
114:     text_contents[[1]]@text
115:   } else {
116:     NULL
117:   }
118: }
119: 
120: truncate_text <- function(text, max_words = 4, max_chars = 40) {
121:   words <- strsplit(text, "\\s+")[[1]]
122:   result <- paste(head(words, max_words), collapse = " ")
123:   if (nchar(result) > max_chars) {
124:     paste0(substr(result, 1, max_chars - 3), "...")
125:   } else {
126:     result
127:   }
128: }
129: 
130: sanitize_filename <- function(text) {
131:   sanitized <- paste(head(strsplit(text, "\\s+")[[1]], 4), collapse = " ")
132:   sanitized <- gsub("[^a-z0-9]+", "_", tolower(sanitized))
133:   sanitized <- gsub("^_+|_+$", "", sanitized)
134:   paste0(sanitized, "__", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
135: }
136: 
137: save_chat <- function(
138:   client,
139:   path = getwd(),
140:   persist = NULL,
141:   existing_file = NULL
142: ) {
143:   turns <- client$get_turns()
144:   if (length(turns) == 0) {
145:     return(invisible(NULL))
146:   }
147: 
148:   if (!is.null(existing_file) && file.exists(existing_file)) {
149:     saveRDS(client, existing_file)
150:     return(invisible(existing_file))
151:   }
152: 
153:   chat_dir <- get_chat_dir(path, persist = persist)
154:   if (!dir.exists(chat_dir)) {
155:     dir.create(chat_dir, recursive = TRUE, showWarnings = FALSE)
156:   }
157: 
158:   user_turns <- Filter(function(turn) turn@role == "user", turns)
159: 
160:   filename <- if (length(user_turns) == 0) {
161:     paste0("new_conversation__", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
162:   } else {
163:     text <- extract_first_text(user_turns[[1]])
164:     if (is.null(text) || nchar(trimws(text)) == 0) {
165:       paste0("new_conversation__", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
166:     } else {
167:       sanitize_filename(text)
168:     }
169:   }
170: 
171:   filepath <- file.path(chat_dir, filename)
172:   saveRDS(client, filepath)
173:   invisible(filepath)
174: }
175: 
176: load_chat <- function(chat_file, fresh_client) {
177:   if (!file.exists(chat_file)) {
178:     cli::cli_abort("Chat file {.path {chat_file}} does not exist.")
179:   }
180: 
181:   old_client <- readRDS(chat_file)
182: 
183:   tryCatch(
184:     {
185:       fresh_client$set_turns(old_client$get_turns())
186:     },
187:     error = function(e) {
188:       cli::cli_inform(c(
189:         "!" = "Chat from previous ellmer version failed to load.",
190:         "i" = "Starting a new chat."
191:       ))
192:     }
193:   )
194: 
195:   fresh_client
