remove_yaml_frontmatter <- function(content) {
  if (length(content) == 0 || content[1] != "---") {
    return(content)
  }

  yaml_end <- which(content == "---")
  if (length(yaml_end) < 2) {
    return(content)
  }

  content[(yaml_end[2] + 1):length(content)]
}

