243: # inconsistent state. Normally, ellmer only adds turns to the Chat history after
244: # a stream completes successfully. When we interrupt mid-stream,
245: # we need to ensure that user/assistant turns alternate back-and-forth, and that
246: # all tool requests have matching tool results.
247: #
248: # For the purposes of this app, interrupts either occur 1) during the tool
249: # calling loop or 2) not.
250: # 1) When during the tool calling loop, just confirm that tool calling loops
251: # appear complete by patching requests that don't have matching results with
252: # a text content.
253: # 2) When not during tool calling, process the streamed text content and
254: # let that form the assistant turn.
255: patch_interrupted_chat <- function(
256:   client,
257:   streamed_content = NULL,
258:   user_input = NULL
259: ) {
260:   # saveRDS(
261:   #   list(client = client, streamed_content = streamed_content, user_input = user_input),
262:   #   "/Users/simoncouch/.config/side/before_patching.rds"
263:   # )
264:   request_ids <- character()
265:   for (turn in client$get_turns()) {
266:     .res <- lapply(turn@contents, function(c) {
267:       if (S7::S7_inherits(c, ellmer::ContentToolRequest)) {
268:         request_ids <<- c(request_ids, c@id)
269:       }
270:     })
271:   }
272: 
273:   result_ids <- character()
274:   for (turn in client$get_turns()) {
275:     .res <- lapply(turn@contents, function(c) {
276:       if (S7::S7_inherits(c, ellmer::ContentToolResult)) {
277:         result_ids <<- c(result_ids, c@request@id)
278:       }
279:     })
280:   }
281: 
282:   requests_without_matches <- request_ids[!request_ids %in% result_ids]
283: 
284:   old_turns <- client$get_turns()
285:   new_turns <- list()
286:   for (turn in old_turns) {
287:     turn@contents <- lapply(turn@contents, function(c) {
288:       if (
289:         S7::S7_inherits(c, ellmer::ContentToolRequest) &&
290:           c@id %in% requests_without_matches
291:       ) {
292:         return(ellmer::ContentText(
293:           paste0("_Tool call to `", c@name, "` interrupted._")
294:         ))
295:       }
296: 
297:       c
298:     })
299: 
300:     new_turns <- c(new_turns, turn)
301:   }
302: 
303:   # If there are requests without matches, the interruption happended during
304:   # the tool calling loop. In that case, just patch the tool call turns and
305:   # don't worry about updating from other streamed content--ellmer already
306:   # had a chance to form complete turns up to the penultimate one.
307:   if (length(requests_without_matches) > 0) {
308:     client$set_turns(new_turns)
309:     return(client)
310:   }
311: 
312:   if (!is.null(streamed_content)) {
313:     text_content <- vapply(
314:       streamed_content,
315:       function(c) S7::S7_inherits(c, ellmer::ContentText),
316:       logical(1)
317:     )
318:     text_content <- paste0(
319:       vapply(streamed_content[text_content], function(c) c@text, character(1)),
320:       collapse = ""
321:     )
322:     text_content <- paste0(text_content, "...\n\n_Streaming interrupted._")
323: 
324:     if (length(new_turns) == 0) {
325:       last_turn_is_assistant <- TRUE
326:     } else {
327:       last_turn_is_assistant <- new_turns[[length(new_turns)]]@role ==
328:         "assistant"
329:     }
330: 
331:     if (last_turn_is_assistant) {
332:       new_turns <- c(
333:         new_turns,
334:         list(
335:           ellmer::Turn("user", list(ellmer::ContentText(user_input))),
336:           ellmer::Turn("assistant", list(ellmer::ContentText(text_content)))
337:         )
338:       )
339:     } else {
340:       # The most recent turn is a user turn, so update its contents with
341:       # the new user input
342:       last_user_turn <- new_turns[[length(new_turns)]]
343:       last_user_turn@contents <- c(
344:         last_user_turn@contents,
345:         ellmer::ContentText(user_input)
346:       )
347:       new_turns[[length(new_turns)]] <- last_user_turn
348: 
349:       new_turns <- c(
350:         new_turns,
351:         list(ellmer::Turn("assistant", list(ellmer::ContentText(text_content))))
352:       )
353:     }
354:   }
355: 
356:   client$set_turns(new_turns)
357:   client
358: }
